INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('non-performing loan', '', '', '[{"en":"The bank''s ratio of non-performing loans rose during the downturn.","zh-TW":"銀行的不良貸款比率在低迷期間上升了。"},{"en":"Non-performing loans are classified after 90 days of missed payments.","zh-TW":"不良貸款在錯過90天還款後分類。"}]', 'phrasal verb'),
('off-balance sheet', '', '', '[{"en":"The lease was structured as off-balance sheet financing.","zh-TW":"租賃被結構為表外融資。"},{"en":"New accounting rules brought many off-balance sheet items onto the balance sheet.","zh-TW":"新會計準則將許多表外項目納入了資產負債表。"}]', 'phrasal verb'),
('offer price', '', '', '[{"en":"The offer price for the shares was set at 10 dollars each.","zh-TW":"股份的要約價定為每股10元。"},{"en":"Investors accepted the offer price after reviewing the acquisition terms.","zh-TW":"投資者審閱收購條款後接受了要約價。"}]', 'phrasal verb'),
('oral agreement', '', '', '[{"en":"An oral agreement may be enforceable but is difficult to prove.","zh-TW":"口頭協議可能具有可執行性，但難以證明。"},{"en":"They should document all terms since the oral agreement is insufficient.","zh-TW":"由於口頭協議不夠充分，他們應記錄所有條款。"}]', 'phrasal verb'),
('outstanding balance', '', '', '[{"en":"The outstanding balance on the invoice was 3000 dollars.","zh-TW":"發票上的未付餘額為3000美元。"},{"en":"Interest accrues daily on the outstanding balance.","zh-TW":"未結清金額每天累積利息。"}]', 'phrasal verb'),
('outsourcing contract', '', '', '[{"en":"The outsourcing contract covers IT support for five years.","zh-TW":"外包合約涵蓋五年的IT支援服務。"},{"en":"Penalties were included in the outsourcing contract for service failures.","zh-TW":"外包合約中包含了服務失敗的罰款條款。"}]', 'phrasal verb'),
('overdue payment', '', '', '[{"en":"The company sent reminders for all overdue payments weekly.","zh-TW":"公司每週發送所有逾期款項的催款通知。"},{"en":"Late fees are applied on overdue payments after 30 days.","zh-TW":"逾期款項30天後將收取滯納金。"}]', 'phrasal verb'),
('overhead allocation', '', '', '[{"en":"Overhead allocation ensures all departments share indirect costs fairly.","zh-TW":"間接費用分配確保所有部門公平分擔間接成本。"},{"en":"The accounting team revised the overhead allocation formula.","zh-TW":"會計團隊修訂了間接費用分配公式。"}]', 'phrasal verb'),
('ownership structure', '', '', '[{"en":"The ownership structure was disclosed in the company prospectus.","zh-TW":"所有權結構在公司招股書中披露了。"},{"en":"A complex ownership structure can complicate governance.","zh-TW":"複雜的所有權結構可能使治理複雜化。"}]', 'phrasal verb'),
('parent company', '', '', '[{"en":"The subsidiary receives financial support from its parent company.","zh-TW":"子公司從母公司獲得財務支持。"},{"en":"The parent company consolidated all subsidiary accounts.","zh-TW":"母公司合併了所有子公司的帳目。"}]', 'phrasal verb'),
('partial ownership', '', '', '[{"en":"The investor acquired partial ownership through a minority stake.","zh-TW":"投資者通過少數股份獲得了部分所有權。"},{"en":"Partial ownership allows risk sharing between multiple investors.","zh-TW":"部分所有權允許多個投資者分擔風險。"}]', 'phrasal verb'),
('pay scale', '', '', '[{"en":"The company revised its pay scale to remain competitive.","zh-TW":"公司修訂了薪資等級以保持競爭力。"},{"en":"She moved up three grades on the pay scale after her promotion.","zh-TW":"晉升後她在薪資等級上晉升了三個級別。"}]', 'phrasal verb'),
('penalty interest', '', '', '[{"en":"Penalty interest of 2% per month is applied to late invoices.","zh-TW":"逾期發票按每月2%計算罰息。"},{"en":"The supplier waived the penalty interest as a gesture of goodwill.","zh-TW":"供應商作為善意表示免除了罰息。"}]', 'phrasal verb'),
('performance bond', '', '', '[{"en":"A performance bond was required before construction could begin.","zh-TW":"施工開始前需要提供履約保證金。"},{"en":"If the contractor fails to perform, the bond can be called.","zh-TW":"如果承包商未能履約，可以要求支付保函。"}]', 'phrasal verb'),
('performance metric', '', '', '[{"en":"Key performance metrics are reviewed monthly by senior management.","zh-TW":"高級管理層每月審查關鍵績效指標。"},{"en":"Performance metrics help the team identify areas for improvement.","zh-TW":"績效指標幫助團隊識別改進領域。"}]', 'phrasal verb'),
('plenary session', '', '', '[{"en":"The conference opened with a plenary session featuring keynote speakers.","zh-TW":"會議以主題演講的全體大會揭幕。"},{"en":"All delegates attended the plenary session for the formal vote.","zh-TW":"所有代表出席了正式投票的全體會議。"}]', 'phrasal verb'),
('policy update', '', '', '[{"en":"A policy update was sent to all employees regarding travel expenses.","zh-TW":"關於差旅費的政策更新已發送給所有員工。"},{"en":"The policy update reflected new regulatory requirements.","zh-TW":"政策更新反映了新的監管要求。"}]', 'phrasal verb'),
('portfolio company', '', '', '[{"en":"The fund has 12 portfolio companies across various sectors.","zh-TW":"該基金在各行業擁有12家投資組合公司。"},{"en":"Portfolio company performance is reviewed quarterly by the fund.","zh-TW":"投資組合公司的績效由基金每季審查。"}]', 'phrasal verb'),
('positive cash flow', '', '', '[{"en":"The startup reached positive cash flow 18 months after launch.","zh-TW":"新創公司在推出18個月後實現了正現金流。"},{"en":"Positive cash flow gives a company the flexibility to invest and grow.","zh-TW":"正現金流使公司具有投資和增長的靈活性。"}]', 'phrasal verb'),
('post-merger integration', '', '', '[{"en":"Post-merger integration was the most difficult phase of the deal.","zh-TW":"合併後整合是交易中最困難的階段。"},{"en":"A dedicated team was formed to oversee post-merger integration.","zh-TW":"成立了一個專屬團隊負責監督合併後整合工作。"}]', 'phrasal verb'),
('pre-tax profit', '', '', '[{"en":"The company reported pre-tax profit of 15 million dollars.","zh-TW":"公司報告了1500萬美元的稅前利潤。"},{"en":"Pre-tax profit grew despite higher raw material costs.","zh-TW":"儘管原材料成本較高，稅前利潤仍然增長了。"}]', 'phrasal verb'),
('price discrimination', '', '', '[{"en":"Airlines use price discrimination by charging different fares for the same seat.","zh-TW":"航空公司對同一座位收取不同票價，實行價格歧視。"},{"en":"Price discrimination maximizes revenue by capturing more consumer surplus.","zh-TW":"價格歧視通過獲取更多消費者剩餘來最大化收入。"}]', 'phrasal verb'),
('procurement policy', '', '', '[{"en":"All purchases must comply with the company procurement policy.","zh-TW":"所有採購必須遵守公司採購政策。"},{"en":"The procurement policy requires competitive bidding for contracts over 50000.","zh-TW":"採購政策要求超過5萬元的合約進行競爭性投標。"}]', 'phrasal verb'),
('profit and loss account', '', '', '[{"en":"The profit and loss account showed a net profit of 8 million.","zh-TW":"損益帳顯示淨利潤為800萬元。"},{"en":"Monthly profit and loss accounts are reviewed by the finance team.","zh-TW":"財務團隊每月審查損益帳。"}]', 'phrasal verb'),
('property rights', '', '', '[{"en":"Strong property rights encourage foreign investment.","zh-TW":"強力的財產權鼓勵外國投資。"},{"en":"The property rights were transferred to the new owner at closing.","zh-TW":"財產權在交割時轉讓給了新業主。"}]', 'phrasal verb'),
('provisional agreement', '', '', '[{"en":"A provisional agreement was signed pending legal review.","zh-TW":"在法律審查待定期間簽署了臨時協議。"},{"en":"The provisional agreement will expire if not converted to a final contract.","zh-TW":"如果沒有轉換為最終合約，臨時協議將失效。"}]', 'phrasal verb'),
('proxy voting', '', '', '[{"en":"Shareholders submitted proxy voting forms before the AGM.","zh-TW":"股東在年度股東大會前提交了委託投票表格。"},{"en":"Proxy voting allows institutional investors to vote on behalf of clients.","zh-TW":"委託投票允許機構投資者代表客戶投票。"}]', 'phrasal verb'),
('public listing', '', '', '[{"en":"The company achieved a public listing after five years of private operation.","zh-TW":"公司在五年私人運營後實現了上市。"},{"en":"A public listing increases access to capital and raises brand profile.","zh-TW":"公開上市增加了資本獲取渠道並提升了品牌形象。"}]', 'phrasal verb'),
('quarterly earnings', '', '', '[{"en":"Quarterly earnings exceeded analyst expectations by 15%.","zh-TW":"季度盈利超出分析師預期15%。"},{"en":"Investors closely watch quarterly earnings reports for growth signals.","zh-TW":"投資者密切關注季度盈利報告以尋找增長信號。"}]', 'phrasal verb'),
('receivables turnover', '', '', '[{"en":"A high receivables turnover ratio indicates efficient collections.","zh-TW":"高應收帳款週轉率表明收款效率高。"},{"en":"The receivables turnover improved after stricter credit terms were enforced.","zh-TW":"在實施更嚴格的信用條款後，應收帳款週轉率有所改善。"}]', 'phrasal verb'),
('recurring expense', '', '', '[{"en":"Rent and utilities are the main recurring expenses.","zh-TW":"租金和水電費是主要的經常性費用。"},{"en":"Recurring expenses should be included in the annual budget plan.","zh-TW":"經常性費用應納入年度預算計劃。"}]', 'phrasal verb'),
('regulatory approval', '', '', '[{"en":"The drug cannot be sold until regulatory approval is granted.","zh-TW":"在獲得監管批准之前，藥物不能出售。"},{"en":"The merger was completed after receiving regulatory approval.","zh-TW":"在獲得監管批准後完成了合併。"}]', 'phrasal verb'),
('regulatory change', '', '', '[{"en":"The company updated its processes to comply with the regulatory change.","zh-TW":"公司更新了流程以遵守監管變更。"},{"en":"Regulatory changes in data protection required major system upgrades.","zh-TW":"資料保護方面的監管變更需要重大系統升級。"}]', 'phrasal verb'),
('restated financial', '', '', '[{"en":"The restated financial results showed lower profits than originally reported.","zh-TW":"經重新申報的財務結果顯示利潤低於原始報告。"},{"en":"An error in accounting led to restated financial statements.","zh-TW":"會計錯誤導致了財務報表的重新申報。"}]', 'phrasal verb'),
('right of first refusal', '', '', '[{"en":"The company holds a right of first refusal on any new share issuance.","zh-TW":"公司持有任何新股發行的優先購買權。"},{"en":"The partnership agreement includes a right of first refusal for buyouts.","zh-TW":"合夥協議包含收購的優先購買權條款。"}]', 'phrasal verb'),
('rollout plan', '', '', '[{"en":"The rollout plan described the phased launch across 10 regions.","zh-TW":"推出計劃描述了在10個地區的分階段推出。"},{"en":"A clear rollout plan minimizes disruption to daily operations.","zh-TW":"清晰的部署計劃最大限度地減少了對日常運營的干擾。"}]', 'phrasal verb'),
('series funding', '', '', '[{"en":"The company completed a 50 million Series C funding round.","zh-TW":"公司完成了5000萬元的C輪融資。"},{"en":"Each series funding round typically values the company higher.","zh-TW":"每輪系列融資通常對公司的估值更高。"}]', 'phrasal verb'),
('service contract', '', '', '[{"en":"The service contract covers maintenance for three years.","zh-TW":"服務合約涵蓋三年的維護服務。"},{"en":"A service contract was signed before the system went live.","zh-TW":"在系統上線前簽署了服務合約。"}]', 'phrasal verb'),
('short-term debt', '', '', '[{"en":"The company refinanced its short-term debt to reduce liquidity pressure.","zh-TW":"公司對短期債務進行了再融資以降低流動性壓力。"},{"en":"Short-term debt is listed as a current liability on the balance sheet.","zh-TW":"短期債務在資產負債表上列為流動負債。"}]', 'phrasal verb'),
('significant other', '', '', '[{"en":"The company must notify all significant others before a major decision.","zh-TW":"公司在重大決策前必須通知所有重大關係方。"},{"en":"Significant others are required to disclose their holdings annually.","zh-TW":"重大關係方需要每年披露其持股情況。"}]', 'phrasal verb'),
('skills gap', '', '', '[{"en":"A training initiative was launched to address the skills gap.","zh-TW":"推出了培訓計劃以解決技能缺口。"},{"en":"The skills gap in digital competencies slowed the transformation.","zh-TW":"數位能力方面的技能缺口減緩了轉型進程。"}]', 'phrasal verb'),
('smart contract', '', '', '[{"en":"Smart contracts execute automatically when conditions are met.","zh-TW":"智能合約在條件滿足時自動執行。"},{"en":"Smart contracts reduce the need for intermediaries in transactions.","zh-TW":"智能合約減少了交易中對中介機構的需求。"}]', 'phrasal verb'),
('solvency ratio', '', '', '[{"en":"A solvency ratio above 20% indicates strong financial health.","zh-TW":"20%以上的償付能力比率表明財務狀況良好。"},{"en":"Regulators require insurance firms to maintain a minimum solvency ratio.","zh-TW":"監管機構要求保險公司維持最低償付能力比率。"}]', 'phrasal verb'),
('source of funds', '', '', '[{"en":"Banks must verify the source of funds for large transactions.","zh-TW":"銀行必須核實大額交易的資金來源。"},{"en":"A clear source of funds declaration is required for compliance.","zh-TW":"合規要求提供明確的資金來源聲明。"}]', 'phrasal verb'),
('stakeholder engagement', '', '', '[{"en":"Stakeholder engagement ensured the policy change had broad support.","zh-TW":"利害關係人參與確保了政策變更獲得廣泛支持。"},{"en":"A stakeholder engagement plan was developed before the project launched.","zh-TW":"項目啟動前制定了利害關係人參與計劃。"}]', 'phrasal verb'),
('strategic partner', '', '', '[{"en":"The company found a strategic partner to enter the Chinese market.","zh-TW":"公司找到了一家戰略夥伴進入中國市場。"},{"en":"A strategic partner provides complementary skills and market access.","zh-TW":"戰略夥伴提供互補的技能和市場准入。"}]', 'phrasal verb'),
('supply contract', '', '', '[{"en":"The company signed a five-year supply contract with the manufacturer.","zh-TW":"公司與製造商簽署了五年供應合約。"},{"en":"A supply contract locks in pricing to protect against cost increases.","zh-TW":"供應合約鎖定了定價以防止成本增加。"}]', 'phrasal verb'),
('take-or-pay contract', '', '', '[{"en":"The gas utility signed a take-or-pay contract for 10 years.","zh-TW":"燃氣公司簽署了一份10年的照付不議合約。"},{"en":"Take-or-pay contracts provide stable revenue for suppliers.","zh-TW":"照付不議合約為供應商提供了穩定的收入。"}]', 'phrasal verb'),
('tangible asset', '', '', '[{"en":"The company strong tangible asset base supports its borrowing capacity.","zh-TW":"公司強大的有形資產基礎支持其借貸能力。"},{"en":"Tangible assets are easier to value than intangible ones.","zh-TW":"有形資產比無形資產更容易估值。"}]', 'phrasal verb'),
('tax avoidance', '', '', '[{"en":"Tax avoidance using legitimate strategies reduces the company tax bill.","zh-TW":"使用合法策略避稅降低了公司的稅務賬單。"},{"en":"There is a fine line between tax avoidance and tax evasion.","zh-TW":"避稅和逃稅之間只有一線之差。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('tax base', '', '', '[{"en":"Broadening the tax base allows governments to lower individual rates.","zh-TW":"擴大稅基允許政府降低個人稅率。"},{"en":"Multinational companies have been accused of eroding the domestic tax base.","zh-TW":"跨國公司被指控侵蝕國內稅基。"}]', 'phrasal verb'),
('tax liability', '', '', '[{"en":"The company''s tax liability was reduced through allowable deductions.","zh-TW":"公司的稅務負債通過允許的扣除額降低了。"},{"en":"Deferred tax liability arises when income is taxed at a future date.","zh-TW":"遞延稅務負債在收入在未來日期被徵稅時產生。"}]', 'phrasal verb'),
('term sheet', '', '', '[{"en":"The VC firm issued a term sheet for a 10 million dollar investment.","zh-TW":"風險投資公司就1000萬元投資出具了條款清單。"},{"en":"Both parties agreed to the term sheet before drafting the final contract.","zh-TW":"雙方在起草最終合約前同意了條款清單。"}]', 'phrasal verb'),
('time value of money', '', '', '[{"en":"The time value of money is the basis for all discounted cash flow analysis.","zh-TW":"貨幣時間價值是所有折現現金流分析的基礎。"},{"en":"Understanding the time value of money is essential for financial planning.","zh-TW":"了解貨幣時間價值對財務規劃至關重要。"}]', 'phrasal verb'),
('trading halt', '', '', '[{"en":"A trading halt was called after the company released its profit warning.","zh-TW":"公司發布盈利預警後，交易暫停被宣佈。"},{"en":"Trading resumed after the one-hour halt.","zh-TW":"一小時暫停後恢復了交易。"}]', 'phrasal verb'),
('transfer pricing', '', '', '[{"en":"Tax authorities scrutinize transfer pricing between related entities.","zh-TW":"稅務機關仔細審查關聯實體之間的轉讓定價。"},{"en":"The company maintained documented transfer pricing policies for audits.","zh-TW":"公司保存了用於審計的書面轉讓定價政策。"}]', 'phrasal verb'),
('treasury management', '', '', '[{"en":"The treasury management team hedged the company currency exposure.","zh-TW":"財資管理團隊對沖了公司的貨幣風險敞口。"},{"en":"Treasury management ensures the company has sufficient liquidity at all times.","zh-TW":"財資管理確保公司隨時有足夠的流動性。"}]', 'phrasal verb'),
('trial balance', '', '', '[{"en":"A trial balance is prepared at the end of each accounting period.","zh-TW":"每個會計期末編制試算表。"},{"en":"Errors in the trial balance led to a delay in the financial statements.","zh-TW":"試算表中的錯誤導致了財務報表的延遲。"}]', 'phrasal verb'),
('turnkey solution', '', '', '[{"en":"The vendor offered a turnkey solution for the factory automation system.","zh-TW":"供應商為工廠自動化系統提供了交鑰匙解決方案。"},{"en":"Clients prefer turnkey solutions to avoid managing multiple vendors.","zh-TW":"客戶偏好交鑰匙解決方案以避免管理多個供應商。"}]', 'phrasal verb'),
('uniform standard', '', '', '[{"en":"Uniform standards ensure consistent quality across all production sites.","zh-TW":"統一標準確保了所有生產地點的一致品質。"},{"en":"The company adopted uniform standards for supplier evaluation.","zh-TW":"公司採用了統一標準進行供應商評估。"}]', 'phrasal verb'),
('value added', '', '', '[{"en":"The consulting firm provides significant value added through industry expertise.","zh-TW":"諮詢公司通過行業專業知識提供了顯著的附加價值。"},{"en":"Manufacturing processes add value added to raw materials.","zh-TW":"製造過程為原材料增加了附加價值。"}]', 'phrasal verb'),
('variable rate', '', '', '[{"en":"The mortgage has a variable rate tied to the prime lending rate.","zh-TW":"抵押貸款採用與最優惠貸款利率掛鉤的浮動利率。"},{"en":"Borrowers on variable rate loans face higher risk when rates rise.","zh-TW":"浮動利率貸款的借款人在利率上升時面臨更高的風險。"}]', 'phrasal verb'),
('vertically integrated', '', '', '[{"en":"The vertically integrated company controls raw materials to retail.","zh-TW":"垂直整合的公司控制著從原材料到零售的全過程。"},{"en":"Vertical integration gives the firm better control over quality and costs.","zh-TW":"垂直整合使公司對品質和成本有更好的控制。"}]', 'phrasal verb'),
('volume discount', '', '', '[{"en":"Customers ordering over 1000 units receive a 10% volume discount.","zh-TW":"訂購超過1000件的客戶可獲得10%的數量折扣。"},{"en":"The volume discount made the bulk order more cost-effective.","zh-TW":"數量折扣使大量訂購更具成本效益。"}]', 'phrasal verb'),
('white label', '', '', '[{"en":"The retailer sells white label products under its own brand name.","zh-TW":"零售商以自己的品牌名稱出售白標產品。"},{"en":"White label banking services allow fintech startups to launch quickly.","zh-TW":"白標銀行服務允許金融科技新創公司快速推出服務。"}]', 'phrasal verb'),
('write down', '', '', '[{"en":"The company wrote down its goodwill by 30 million dollars.","zh-TW":"公司將商譽減記了3000萬元。"},{"en":"Inventory was written down after the market price fell below cost.","zh-TW":"市場價格跌破成本後，庫存被減記了。"}]', 'phrasal verb'),
('absorption costing', '', '', '[{"en":"Under absorption costing, fixed overhead is included in product cost.","zh-TW":"在完全成本法下，固定費用計入產品成本。"},{"en":"Absorption costing can distort profit when inventory levels change.","zh-TW":"當庫存水準變化時，完全成本法可能扭曲利潤。"}]', 'phrasal verb'),
('asset-backed securities', '', '', '[{"en":"Mortgage-backed securities are a type of asset-backed securities.","zh-TW":"抵押支持證券是資產抵押證券的一種。"},{"en":"Asset-backed securities played a major role in the financial crisis.","zh-TW":"資產抵押證券在金融危機中扮演了重要角色。"}]', 'phrasal verb'),
('base salary', '', '', '[{"en":"She negotiated a higher base salary before accepting the offer.","zh-TW":"她在接受邀約前談判了更高的基本薪資。"},{"en":"Base salary is supplemented by performance-linked bonuses.","zh-TW":"基本薪資由績效掛鉤的獎金補充。"}]', 'phrasal verb'),
('batch production', '', '', '[{"en":"The bakery uses batch production to make different bread types daily.","zh-TW":"麵包店使用批量生產每天製作不同種類的麵包。"},{"en":"Batch production offers flexibility but may result in higher per-unit costs.","zh-TW":"批量生產提供靈活性但可能導致較高的單位成本。"}]', 'phrasal verb'),
('benchmarking study', '', '', '[{"en":"The consultants conducted a benchmarking study on HR practices.","zh-TW":"顧問們對人力資源實踐進行了標竿研究。"},{"en":"The benchmarking study revealed gaps in our customer service scores.","zh-TW":"標竿研究揭示了我們客戶服務評分中的差距。"}]', 'phrasal verb'),
('bid document', '', '', '[{"en":"All bid documents must be received before the 5 PM deadline.","zh-TW":"所有投標文件必須在下午5點截止日期前收到。"},{"en":"The bid documents included technical specifications and pricing.","zh-TW":"投標文件包括技術規格和定價。"}]', 'phrasal verb'),
('blended rate', '', '', '[{"en":"The blended rate on the portfolio loans was 4.8%.","zh-TW":"投資組合貸款的混合利率為4.8%。"},{"en":"Refinancing multiple loans into one reduces the blended rate.","zh-TW":"將多筆貸款合併再融資降低了混合利率。"}]', 'phrasal verb'),
('bulk purchase', '', '', '[{"en":"A bulk purchase of office supplies cut unit costs by 25%.","zh-TW":"批量採購辦公用品使單位成本降低了25%。"},{"en":"The company negotiated a bulk purchase agreement for raw materials.","zh-TW":"公司為原材料談判了批量採購協議。"}]', 'phrasal verb'),
('buyback program', '', '', '[{"en":"The board approved a 100 million dollar buyback program.","zh-TW":"董事會批准了1億美元的回購計劃。"},{"en":"A share buyback program signals management confidence in the stock.","zh-TW":"股份回購計劃表明管理層對股票的信心。"}]', 'phrasal verb'),
('capital injection', '', '', '[{"en":"The government provided a capital injection to rescue the failing bank.","zh-TW":"政府向瀕臨倒閉的銀行提供了資本注入以救援。"},{"en":"A capital injection by private investors prevented bankruptcy.","zh-TW":"私人投資者的資本注入防止了破產。"}]', 'phrasal verb'),
('case study', '', '', '[{"en":"The professor used a case study to illustrate supply chain risks.","zh-TW":"教授使用案例研究來說明供應鏈風險。"},{"en":"The marketing team prepared a case study on the product launch success.","zh-TW":"行銷團隊準備了一個關於產品發佈成功的案例研究。"}]', 'phrasal verb'),
('central bank', '', '', '[{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"中央銀行提高利率以應對通貨膨脹。"},{"en":"Central bank decisions affect borrowing costs across the economy.","zh-TW":"中央銀行的決定影響整個經濟的借貸成本。"}]', 'phrasal verb'),
('chief financial officer', '', '', '[{"en":"The CFO presented the annual results to the board.","zh-TW":"財務長向董事會報告了年度業績。"},{"en":"She was promoted to chief financial officer after 10 years with the firm.","zh-TW":"她在公司工作10年後晉升為財務長。"}]', 'phrasal verb'),
('commission rate', '', '', '[{"en":"The sales rep earns a 5% commission rate on all direct sales.","zh-TW":"銷售代表從所有直接銷售中賺取5%的佣金率。"},{"en":"The company raised the commission rate to attract top salespeople.","zh-TW":"公司提高了佣金率以吸引頂尖銷售人員。"}]', 'phrasal verb'),
('competitive tender', '', '', '[{"en":"The city issued a competitive tender for the road construction project.","zh-TW":"市政府為道路建設項目發出了競爭性招標。"},{"en":"All vendors were invited to submit bids through competitive tender.","zh-TW":"所有供應商受邀通過競爭性招標提交投標書。"}]', 'phrasal verb'),
('consulting fees', '', '', '[{"en":"Consulting fees amounted to 200000 dollars for the project.","zh-TW":"項目的諮詢費共計20萬元。"},{"en":"The company reduced consulting fees by developing internal expertise.","zh-TW":"公司通過培養內部專業知識降低了諮詢費。"}]', 'phrasal verb'),
('convertible bond', '', '', '[{"en":"The company issued convertible bonds to raise growth capital.","zh-TW":"公司發行可轉換債券以籌集增長資本。"},{"en":"Investors prefer convertible bonds for downside protection.","zh-TW":"投資者偏好可轉換債券以獲得下行保護。"}]', 'phrasal verb'),
('coordination meeting', '', '', '[{"en":"A weekly coordination meeting ensures all teams are aligned.","zh-TW":"每週協調會議確保所有團隊保持一致。"},{"en":"The coordination meeting resolved the inter-departmental scheduling conflict.","zh-TW":"協調會議解決了部門間的排程衝突。"}]', 'phrasal verb'),
('corporate communications', '', '', '[{"en":"The corporate communications team drafted the press release.","zh-TW":"企業傳播團隊起草了新聞稿。"},{"en":"Effective corporate communications builds reputation and trust.","zh-TW":"有效的企業傳播建立了聲譽和信任。"}]', 'phrasal verb'),
('corporate ethics', '', '', '[{"en":"The company''s corporate ethics policy prohibits conflicts of interest.","zh-TW":"公司的企業倫理政策禁止利益衝突。"},{"en":"Corporate ethics training is mandatory for all employees.","zh-TW":"企業倫理培訓對所有員工是強制性的。"}]', 'phrasal verb'),
('currency hedging', '', '', '[{"en":"The company uses currency hedging to protect overseas earnings.","zh-TW":"公司使用貨幣對沖保護海外收益。"},{"en":"Currency hedging is essential for firms with significant foreign revenues.","zh-TW":"對於擁有大量外幣收入的公司，貨幣對沖至關重要。"}]', 'phrasal verb'),
('customer retention', '', '', '[{"en":"Loyalty programs are a key tool for customer retention.","zh-TW":"忠誠計劃是客戶保留的關鍵工具。"},{"en":"High customer retention reduces the cost of acquiring new clients.","zh-TW":"高客戶保留率降低了獲取新客戶的成本。"}]', 'phrasal verb'),
('customer segmentation', '', '', '[{"en":"Customer segmentation allows for targeted marketing campaigns.","zh-TW":"客戶細分允許有針對性的行銷活動。"},{"en":"The company used customer segmentation to improve service personalization.","zh-TW":"公司使用客戶細分改善了服務個性化。"}]', 'phrasal verb'),
('data governance', '', '', '[{"en":"The data governance policy defines who can access sensitive information.","zh-TW":"資料治理政策定義了誰可以存取敏感資訊。"},{"en":"Strong data governance ensures compliance with privacy regulations.","zh-TW":"強力的資料治理確保遵守隱私法規。"}]', 'phrasal verb'),
('delivery note', '', '', '[{"en":"The warehouse manager signed the delivery note on receipt.","zh-TW":"倉庫管理員在收貨時簽署了送貨單。"},{"en":"The delivery note listed 500 units of the product.","zh-TW":"送貨單上列明了500件產品。"}]', 'phrasal verb'),
('disclosure requirements', '', '', '[{"en":"Listed companies must comply with all disclosure requirements.","zh-TW":"上市公司必須遵守所有披露要求。"},{"en":"Failure to meet disclosure requirements can result in regulatory action.","zh-TW":"未能滿足披露要求可能導致監管行動。"}]', 'phrasal verb'),
('double-entry bookkeeping', '', '', '[{"en":"Double-entry bookkeeping ensures the accounting equation always balances.","zh-TW":"複式記帳法確保會計等式始終平衡。"},{"en":"The accounting software automatically applies double-entry bookkeeping.","zh-TW":"會計軟體自動應用複式記帳法。"}]', 'phrasal verb'),
('economic downturn', '', '', '[{"en":"Sales fell sharply during the economic downturn.","zh-TW":"經濟低迷期間銷售大幅下降。"},{"en":"Companies that manage costs well can survive an economic downturn.","zh-TW":"善於管理成本的公司能夠度過經濟下滑。"}]', 'phrasal verb'),
('end-of-year review', '', '', '[{"en":"The end-of-year review identified areas for improvement in Q1.","zh-TW":"年終審查識別了第一季度的改進領域。"},{"en":"All departments submitted end-of-year review reports by December 31.","zh-TW":"所有部門在12月31日前提交了年終審查報告。"}]', 'phrasal verb'),
('evaluate performance', '', '', '[{"en":"Managers evaluate performance using a set of measurable criteria.","zh-TW":"管理者使用一套可衡量的標準評估績效。"},{"en":"The project was evaluated for performance against the original budget.","zh-TW":"項目按照原始預算評估了其績效。"}]', 'phrasal verb'),
('exclusion clause', '', '', '[{"en":"The exclusion clause exempted the company from liability for force majeure.","zh-TW":"免責條款使公司免於對不可抗力事件承擔責任。"},{"en":"The exclusion clause was challenged and found to be unenforceable.","zh-TW":"免責條款受到質疑，被認定為不可執行。"}]', 'phrasal verb'),
('expenditure control', '', '', '[{"en":"Expenditure control was tightened after the budget overrun.","zh-TW":"預算超支後加強了支出控制。"},{"en":"Monthly expenditure control reports were submitted to the finance committee.","zh-TW":"每月支出控制報告提交給財務委員會。"}]', 'phrasal verb'),
('expense claim', '', '', '[{"en":"All expense claims must be submitted within 30 days of the expense.","zh-TW":"所有費用報銷申請必須在費用發生後30天內提交。"},{"en":"The expense claim was rejected as it lacked supporting receipts.","zh-TW":"費用報銷申請因缺少支持收據而被拒絕。"}]', 'phrasal verb'),
('external audit', '', '', '[{"en":"The external audit confirmed the accuracy of the financial statements.","zh-TW":"外部審計確認了財務報表的準確性。"},{"en":"Listed companies are required to undergo an annual external audit.","zh-TW":"上市公司必須接受年度外部審計。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('fee schedule', '', '', '[{"en":"Clients can review the fee schedule before engaging services.","zh-TW":"客戶可在使用服務前查看費用明細表。"},{"en":"The fee schedule was revised to reflect increased operating costs.","zh-TW":"費用明細表經修訂以反映增加的運營成本。"}]', 'phrasal verb'),
('file a complaint', '', '', '[{"en":"The customer filed a complaint with the consumer protection agency.","zh-TW":"客戶向消費者保護機構提出了投訴。"},{"en":"Filing a complaint triggers a formal investigation process.","zh-TW":"提出投訴觸發了正式調查流程。"}]', 'phrasal verb'),
('finance team', '', '', '[{"en":"The finance team prepared the quarterly budget review.","zh-TW":"財務團隊準備了季度預算審查。"},{"en":"Any large purchase requires sign-off from the finance team.","zh-TW":"任何大額採購都需要財務團隊的批准。"}]', 'phrasal verb'),
('financial close', '', '', '[{"en":"The project reached financial close after months of negotiations.","zh-TW":"經過幾個月的談判後，項目完成了財務交割。"},{"en":"Financial close confirms all funding is in place for the transaction.","zh-TW":"財務交割確認交易的所有資金已到位。"}]', 'phrasal verb'),
('financial intermediary', '', '', '[{"en":"Banks act as financial intermediaries between depositors and borrowers.","zh-TW":"銀行在存款人和借款人之間充當金融中介。"},{"en":"Financial intermediaries reduce transaction costs in capital markets.","zh-TW":"金融中介降低了資本市場的交易成本。"}]', 'phrasal verb'),
('fixed income', '', '', '[{"en":"Retirees often prefer fixed income investments for stable returns.","zh-TW":"退休人員通常偏好固定收益投資以獲得穩定回報。"},{"en":"The fund shifted toward fixed income securities as rates rose.","zh-TW":"隨著利率上升，基金轉向了固定收益證券。"}]', 'phrasal verb'),
('general expenses', '', '', '[{"en":"General expenses rose 10% due to higher utilities and rent.","zh-TW":"由於水電費和租金上漲，一般費用增加了10%。"},{"en":"The finance team tracks general expenses monthly against budget.","zh-TW":"財務團隊每月按預算追蹤一般費用。"}]', 'phrasal verb'),
('goodwill impairment', '', '', '[{"en":"The annual goodwill impairment test resulted in a 20 million write-down.","zh-TW":"年度商譽減損測試導致了2000萬元的減記。"},{"en":"Goodwill impairment charges reduced the company reported earnings.","zh-TW":"商譽減損費用降低了公司的報告盈利。"}]', 'phrasal verb'),
('grant period', '', '', '[{"en":"All project activities must be completed within the grant period.","zh-TW":"所有項目活動必須在補助期間內完成。"},{"en":"The grant period was extended to allow for construction delays.","zh-TW":"補助期間因施工延誤而延長了。"}]', 'phrasal verb'),
('group dynamics', '', '', '[{"en":"Positive group dynamics lead to higher team productivity.","zh-TW":"積極的群體動態帶來了更高的團隊生產力。"},{"en":"The facilitator worked to improve group dynamics during the workshop.","zh-TW":"主持人在研討會期間努力改善群體動態。"}]', 'phrasal verb'),
('hedging strategy', '', '', '[{"en":"The treasury team adopted a hedging strategy to protect against oil price rises.","zh-TW":"財資團隊採用了對沖策略以防止油價上漲。"},{"en":"A well-designed hedging strategy reduces earnings volatility.","zh-TW":"設計良好的對沖策略降低了盈利波動性。"}]', 'phrasal verb'),
('hire on a contract', '', '', '[{"en":"The company hired 20 specialists on a contract basis for the rollout.","zh-TW":"公司以合約方式聘用了20名專家負責推出工作。"},{"en":"Hiring on a contract is more flexible but may increase training costs.","zh-TW":"以合約方式聘用更具靈活性但可能增加培訓成本。"}]', 'phrasal verb'),
('hostile takeover', '', '', '[{"en":"The board adopted a poison pill to deter a hostile takeover.","zh-TW":"董事會採用了毒丸策略阻止惡意收購。"},{"en":"A hostile takeover bid was made at a 30% premium to the share price.","zh-TW":"以高於股價30%的溢價發出了惡意收購要約。"}]', 'phrasal verb'),
('impairment test', '', '', '[{"en":"The annual impairment test showed no reduction in goodwill value.","zh-TW":"年度減損測試顯示商譽價值沒有下降。"},{"en":"Impairment tests are triggered by adverse market or business conditions.","zh-TW":"減損測試由不利的市場或業務條件觸發。"}]', 'phrasal verb'),
('in arrears', '', '', '[{"en":"The tenant was three months in arrears on the rent.","zh-TW":"租客的租金拖欠了三個月。"},{"en":"Wages paid in arrears means payment follows the work period.","zh-TW":"延後支付的薪資意味著付款在工作期結束後進行。"}]', 'phrasal verb'),
('incentive scheme', '', '', '[{"en":"The new incentive scheme doubled the sales team average performance.","zh-TW":"新激勵計劃使銷售團隊的平均績效翻倍了。"},{"en":"An effective incentive scheme aligns individual goals with company objectives.","zh-TW":"有效的激勵計劃使個人目標與公司目標保持一致。"}]', 'phrasal verb'),
('independent contractor', '', '', '[{"en":"The company hired independent contractors to avoid long-term employment costs.","zh-TW":"公司聘用了獨立承包商以避免長期雇傭成本。"},{"en":"Independent contractors are responsible for their own taxes and benefits.","zh-TW":"獨立承包商負責自己的稅務和福利。"}]', 'phrasal verb'),
('industrial action', '', '', '[{"en":"Workers voted to take industrial action over the pay dispute.","zh-TW":"工人投票通過採取工業行動以抗議薪資糾紛。"},{"en":"The company sought to avoid industrial action by entering talks.","zh-TW":"公司尋求通過談判避免工業行動。"}]', 'phrasal verb'),
('inflation hedge', '', '', '[{"en":"Real estate is often used as an inflation hedge.","zh-TW":"房地產常被用作通脹對沖工具。"},{"en":"Gold has traditionally served as an inflation hedge for investors.","zh-TW":"黃金傳統上作為投資者的通脹對沖工具。"}]', 'phrasal verb'),
('information technology', '', '', '[{"en":"The information technology budget was increased to support digital transformation.","zh-TW":"為支持數位轉型，資訊技術預算增加了。"},{"en":"Information technology improvements reduced processing time by half.","zh-TW":"資訊技術改進將處理時間縮短了一半。"}]', 'phrasal verb'),
('initial investment', '', '', '[{"en":"The initial investment in the plant was 10 million dollars.","zh-TW":"工廠的初始投資為1000萬元。"},{"en":"The payback period for the initial investment was estimated at four years.","zh-TW":"初始投資的回收期估計為四年。"}]', 'phrasal verb'),
('input cost', '', '', '[{"en":"Rising input costs squeezed the manufacturer''s margins.","zh-TW":"上漲的投入成本壓縮了製造商的利潤率。"},{"en":"The company passed higher input costs on to customers through price increases.","zh-TW":"公司通過提高價格將更高的投入成本轉嫁給了客戶。"}]', 'phrasal verb'),
('intellectual property rights', '', '', '[{"en":"The company vigorously protects its intellectual property rights.","zh-TW":"公司積極保護其智慧財產權。"},{"en":"Intellectual property rights are often the most valuable asset in tech companies.","zh-TW":"在科技公司中，智慧財產權往往是最有價值的資產。"}]', 'phrasal verb'),
('interest rate risk', '', '', '[{"en":"The bond portfolio is exposed to significant interest rate risk.","zh-TW":"債券投資組合面臨重大利率風險。"},{"en":"The company uses swaps to hedge its interest rate risk.","zh-TW":"公司使用掉期合約對沖利率風險。"}]', 'phrasal verb'),
('invest in technology', '', '', '[{"en":"The company invested heavily in technology to improve service delivery.","zh-TW":"公司在技術方面投入了大量資金以改善服務交付。"},{"en":"Investing in technology can reduce long-term operational costs.","zh-TW":"投資技術可以降低長期運營成本。"}]', 'phrasal verb'),
('invoice factoring', '', '', '[{"en":"Invoice factoring provided the startup with immediate working capital.","zh-TW":"發票保理為新創公司提供了即時營運資金。"},{"en":"Invoice factoring is a fast way to improve short-term cash flow.","zh-TW":"發票保理是改善短期現金流的快速方法。"}]', 'phrasal verb'),
('job performance', '', '', '[{"en":"Regular feedback improves job performance over time.","zh-TW":"定期反饋隨時間推移改善了工作績效。"},{"en":"Job performance is reviewed annually as part of the appraisal process.","zh-TW":"工作績效作為評估流程的一部分每年審查一次。"}]', 'phrasal verb'),
('labor contract', '', '', '[{"en":"All new employees must sign a labor contract before starting.","zh-TW":"所有新員工在開始工作前必須簽署勞動合約。"},{"en":"The labor contract specifies salary, hours, and benefits.","zh-TW":"勞動合約規定了薪資、工時和福利。"}]', 'phrasal verb'),
('labor force', '', '', '[{"en":"A growing labor force drove economic expansion in the region.","zh-TW":"不斷增長的勞動力推動了該地區的經濟擴張。"},{"en":"The company needed to upskill its labor force to meet digital demands.","zh-TW":"公司需要提升其勞動力技能以滿足數位需求。"}]', 'phrasal verb'),
('land acquisition', '', '', '[{"en":"The land acquisition for the new factory cost 20 million.","zh-TW":"新工廠的土地收購花費了2000萬元。"},{"en":"Land acquisition is the first step in the real estate development process.","zh-TW":"土地收購是房地產開發流程的第一步。"}]', 'phrasal verb'),
('leadership development', '', '', '[{"en":"The company invests in leadership development for high-potential employees.","zh-TW":"公司為高潛力員工投資領導力發展。"},{"en":"Leadership development programs improve succession planning outcomes.","zh-TW":"領導力發展計劃改善了繼任規劃成果。"}]', 'phrasal verb'),
('lean manufacturing', '', '', '[{"en":"Lean manufacturing reduced waste by 40% in the first year.","zh-TW":"精益生產在第一年將浪費減少了40%。"},{"en":"Lean manufacturing principles are widely used in automotive production.","zh-TW":"精益生產原則在汽車製造中被廣泛應用。"}]', 'phrasal verb'),
('liability management', '', '', '[{"en":"The treasury team conducted a liability management exercise to reduce costs.","zh-TW":"財資團隊進行了負債管理操作以降低成本。"},{"en":"Liability management involves refinancing, repurchasing, and restructuring debt.","zh-TW":"負債管理涉及債務再融資、回購和重組。"}]', 'phrasal verb'),
('loan repayment', '', '', '[{"en":"Monthly loan repayments were structured over 10 years.","zh-TW":"每月貸款還款期設定為10年。"},{"en":"The company prioritized loan repayment to improve its credit rating.","zh-TW":"公司優先償還貸款以改善其信用評級。"}]', 'phrasal verb'),
('loss aversion', '', '', '[{"en":"Loss aversion can prevent investors from selling underperforming assets.","zh-TW":"損失厭惡可能阻止投資者出售績效不佳的資產。"},{"en":"Understanding loss aversion is important for financial advisors.","zh-TW":"了解損失厭惡對財務顧問至關重要。"}]', 'phrasal verb'),
('management fee', '', '', '[{"en":"The fund charges an annual management fee of 1.5%.","zh-TW":"基金收取每年1.5%的管理費。"},{"en":"Management fees were reduced to attract more investors.","zh-TW":"管理費降低了以吸引更多投資者。"}]', 'phrasal verb'),
('maturity date', '', '', '[{"en":"The bond reaches its maturity date on December 31.","zh-TW":"債券在12月31日到達到期日。"},{"en":"The company planned to refinance the debt before its maturity date.","zh-TW":"公司計劃在到期日前對債務進行再融資。"}]', 'phrasal verb'),
('minimum order quantity', '', '', '[{"en":"The supplier requires a minimum order quantity of 500 units.","zh-TW":"供應商要求最小訂購量為500件。"},{"en":"The startup struggled to meet the minimum order quantity.","zh-TW":"新創公司難以達到最小訂購量。"}]', 'phrasal verb'),
('minority interest', '', '', '[{"en":"The consolidated accounts include minority interest from the joint venture.","zh-TW":"合並帳目包括來自合資企業的少數股東權益。"},{"en":"Minority interest shareholders received a proportionate dividend.","zh-TW":"少數股東權益持有人獲得了按比例的股息。"}]', 'phrasal verb'),
('negative equity', '', '', '[{"en":"Homeowners in declining markets may find themselves in negative equity.","zh-TW":"在下跌市場中，房主可能發現自己陷入負資產。"},{"en":"Negative equity prevents the company from securing further financing.","zh-TW":"負資產阻止公司獲得進一步的融資。"}]', 'phrasal verb'),
('operating budget', '', '', '[{"en":"The operating budget for next year was set at 5 million.","zh-TW":"下一年的運營預算設定為500萬元。"},{"en":"All departments submitted their plans for the annual operating budget.","zh-TW":"所有部門提交了年度運營預算計劃。"}]', 'phrasal verb'),
('operating expenditure', '', '', '[{"en":"The company cut operating expenditure by 15% through efficiency measures.","zh-TW":"公司通過效率措施削減了15%的運營支出。"},{"en":"Operating expenditure is deducted from revenue to calculate operating profit.","zh-TW":"運營支出從收入中扣除以計算營業利潤。"}]', 'phrasal verb'),
('option contract', '', '', '[{"en":"The option contract gave the company the right to acquire the land.","zh-TW":"選擇權合約賦予公司收購土地的權利。"},{"en":"Investors use option contracts to hedge downside risk.","zh-TW":"投資者使用期權合約對沖下行風險。"}]', 'phrasal verb'),
('order fulfillment', '', '', '[{"en":"The company improved order fulfillment speed by automating the warehouse.","zh-TW":"公司通過自動化倉庫提高了訂單履行速度。"},{"en":"Order fulfillment accuracy is tracked as a key performance indicator.","zh-TW":"訂單履行準確性作為關鍵績效指標進行追蹤。"}]', 'phrasal verb'),
('organizational restructuring', '', '', '[{"en":"Organizational restructuring merged three divisions into one.","zh-TW":"組織重組將三個部門合併為一個。"},{"en":"The organizational restructuring improved reporting lines and accountability.","zh-TW":"組織重組改善了匯報線和問責制。"}]', 'phrasal verb'),
('package deal', '', '', '[{"en":"The supplier offered a package deal including installation and training.","zh-TW":"供應商提供了包括安裝和培訓的套裝方案。"},{"en":"Negotiators agreed on a package deal covering wages and benefits.","zh-TW":"談判者就包含薪資和福利的一攬子交易達成了協議。"}]', 'phrasal verb'),
('patent application', '', '', '[{"en":"The company filed a patent application for its new manufacturing process.","zh-TW":"公司為其新製造工藝提交了專利申請。"},{"en":"A successful patent application blocks competitors from copying the invention.","zh-TW":"成功的專利申請阻止競爭者複製該發明。"}]', 'phrasal verb'),
('payroll system', '', '', '[{"en":"The new payroll system automates tax deductions and payments.","zh-TW":"新的薪資系統自動化了稅款扣除和支付。"},{"en":"The payroll system was migrated to cloud-based software.","zh-TW":"薪資系統遷移到了雲端軟體。"}]', 'phrasal verb'),
('pension fund', '', '', '[{"en":"The pension fund invests in a mix of equities and bonds.","zh-TW":"退休基金投資於股票和債券的組合。"},{"en":"The company''s pension fund liability grew with an aging workforce.","zh-TW":"隨著員工老齡化，公司的退休基金負債增加了。"}]', 'phrasal verb'),
('periodic review', '', '', '[{"en":"A periodic review of supplier contracts is conducted annually.","zh-TW":"供應商合約的定期審查每年進行一次。"},{"en":"Periodic reviews ensure the strategy remains relevant to market conditions.","zh-TW":"定期審查確保策略與市場條件保持相關性。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('personal liability', '', '', '[{"en":"Sole traders face personal liability for all business debts.","zh-TW":"個體經營者對所有商業債務承擔個人責任。"},{"en":"The court held the director personally liable for the company losses.","zh-TW":"法院追究董事對公司損失的個人責任。"}]', 'phrasal verb'),
('planning permission', '', '', '[{"en":"The developer obtained planning permission before construction began.","zh-TW":"開發商在施工開始前獲得了規劃許可。"},{"en":"Planning permission was refused due to concerns about traffic impact.","zh-TW":"由於對交通影響的擔憂，規劃許可被拒絕了。"}]', 'phrasal verb'),
('post-tax profit', '', '', '[{"en":"Post-tax profit attributable to shareholders was 8 million.","zh-TW":"歸屬股東的稅後利潤為800萬元。"},{"en":"The post-tax profit margin improved after the tax reform.","zh-TW":"稅後利潤率在稅制改革後有所改善。"}]', 'phrasal verb'),
('preferred stock', '', '', '[{"en":"The investor received preferred stock with a guaranteed 6% dividend.","zh-TW":"投資者獲得了保證6%股息的優先股。"},{"en":"Preferred stock holders take priority in the event of liquidation.","zh-TW":"在清算時，優先股持有人享有優先權。"}]', 'phrasal verb'),
('premium pricing', '', '', '[{"en":"The luxury brand maintains premium pricing to reinforce exclusivity.","zh-TW":"奢侈品品牌維持溢價定價以強化排他性。"},{"en":"Premium pricing is only sustainable if the product delivers exceptional quality.","zh-TW":"只有產品提供卓越品質，溢價定價才是可持續的。"}]', 'phrasal verb'),
('pro forma', '', '', '[{"en":"The pro forma accounts excluded one-off restructuring charges.","zh-TW":"備考帳目排除了一次性重組費用。"},{"en":"Investors should review both actual and pro forma earnings carefully.","zh-TW":"投資者應仔細審查實際和備考盈利。"}]', 'phrasal verb'),
('productivity improvement', '', '', '[{"en":"Automation led to a 25% productivity improvement.","zh-TW":"自動化帶來了25%的生產力改善。"},{"en":"The productivity improvement program reduced manufacturing costs significantly.","zh-TW":"生產力改善計劃顯著降低了製造成本。"}]', 'phrasal verb'),
('profit warning', '', '', '[{"en":"The company issued a profit warning after weak Q3 sales.","zh-TW":"公司在第三季度銷售疲弱後發出了盈利預警。"},{"en":"A profit warning typically leads to a sharp drop in share price.","zh-TW":"盈利預警通常導致股價大幅下跌。"}]', 'phrasal verb'),
('quantitative analysis', '', '', '[{"en":"Quantitative analysis confirmed the positive correlation between ad spend and sales.","zh-TW":"定量分析確認了廣告支出和銷售之間的正相關關係。"},{"en":"Fund managers use quantitative analysis to identify trading opportunities.","zh-TW":"基金管理人使用定量分析識別交易機會。"}]', 'phrasal verb'),
('redundancy package', '', '', '[{"en":"The company offered a generous redundancy package to affected employees.","zh-TW":"公司向受影響的員工提供了慷慨的裁員補償方案。"},{"en":"The redundancy package included three months pay and career support.","zh-TW":"裁員補償方案包括三個月薪資和職業支持。"}]', 'phrasal verb'),
('refund policy', '', '', '[{"en":"The company updated its refund policy to a 30-day returns window.","zh-TW":"公司將退款政策更新為30天退貨窗口。"},{"en":"Clear refund policies build customer trust and reduce disputes.","zh-TW":"清晰的退款政策建立了客戶信任並減少了糾紛。"}]', 'phrasal verb'),
('relate to', '', '', '[{"en":"The legal matter relates to a contract dispute from 2023.","zh-TW":"該法律事項與2023年的合約糾紛有關。"},{"en":"All queries relating to billing should be directed to accounts.","zh-TW":"所有與計費相關的查詢應聯絡帳務部門。"}]', 'phrasal verb'),
('release funds', '', '', '[{"en":"The finance committee approved and released funds for the renovation.","zh-TW":"財務委員會批准並撥付了翻新資金。"},{"en":"Funds are released in stages as project milestones are reached.","zh-TW":"隨著項目里程碑的實現，資金分階段釋放。"}]', 'phrasal verb'),
('renewal terms', '', '', '[{"en":"The supplier proposed new pricing as part of the renewal terms.","zh-TW":"供應商提出了新定價作為續約條款的一部分。"},{"en":"Renewal terms were accepted without modification by both parties.","zh-TW":"雙方未作修改地接受了續約條款。"}]', 'phrasal verb'),
('repayment schedule', '', '', '[{"en":"The bank approved a flexible repayment schedule tied to revenue.","zh-TW":"銀行批准了與收入掛鉤的彈性還款計劃。"},{"en":"Missing payments on the repayment schedule triggers penalty clauses.","zh-TW":"未按還款計劃支付款項觸發了罰款條款。"}]', 'phrasal verb'),
('restructuring charge', '', '', '[{"en":"The company recorded a 50 million restructuring charge for the layoffs.","zh-TW":"公司為裁員記錄了5000萬元的重組費用。"},{"en":"Restructuring charges were excluded from the adjusted profit figures.","zh-TW":"重組費用從調整後的利潤數字中排除了。"}]', 'phrasal verb'),
('sales forecast', '', '', '[{"en":"The sales forecast was revised down after poor August results.","zh-TW":"在八月業績不佳後，銷售預測被下調了。"},{"en":"An accurate sales forecast allows production to be planned effectively.","zh-TW":"準確的銷售預測允許有效規劃生產。"}]', 'phrasal verb'),
('sales pipeline', '', '', '[{"en":"The sales pipeline shows deals worth 5 million in the next quarter.","zh-TW":"銷售管道顯示下個季度有價值500萬元的交易。"},{"en":"Regular pipeline reviews identify stalled opportunities.","zh-TW":"定期管道審查識別了停滯的商機。"}]', 'phrasal verb'),
('secondary offering', '', '', '[{"en":"The company raised 200 million through a secondary offering.","zh-TW":"公司通過二次發行籌集了2億元。"},{"en":"The secondary offering diluted existing shareholders by 5%.","zh-TW":"二次發行使現有股東的股份稀釋了5%。"}]', 'phrasal verb'),
('senior management', '', '', '[{"en":"Senior management approved the expansion into three new markets.","zh-TW":"高級管理層批准了進入三個新市場的擴張。"},{"en":"Decisions of this magnitude must be escalated to senior management.","zh-TW":"這種規模的決策必須升級至高級管理層。"}]', 'phrasal verb'),
('shareholder meeting', '', '', '[{"en":"The annual shareholder meeting approved the dividend payment.","zh-TW":"年度股東大會批准了股息支付。"},{"en":"Proxy votes were submitted before the shareholder meeting.","zh-TW":"委託投票在股東大會前提交了。"}]', 'phrasal verb'),
('short position', '', '', '[{"en":"The fund took a short position in the overvalued stock.","zh-TW":"基金對被高估的股票持有空頭部位。"},{"en":"Short positions expose traders to unlimited losses if prices rise.","zh-TW":"如果價格上漲，空頭部位使交易者面臨無限損失。"}]', 'phrasal verb'),
('signature block', '', '', '[{"en":"All contracts include a signature block for both parties.","zh-TW":"所有合約都包含雙方的簽名欄。"},{"en":"Please ensure your email signature block includes your direct number.","zh-TW":"請確保您的電子郵件署名區塊包含您的直線電話。"}]', 'phrasal verb'),
('single-source supplier', '', '', '[{"en":"Relying on a single-source supplier creates vulnerability to disruption.","zh-TW":"依賴單一來源供應商造成了對干擾的脆弱性。"},{"en":"The company diversified after its single-source supplier shut down.","zh-TW":"其單一來源供應商倒閉後，公司進行了多元化。"}]', 'phrasal verb'),
('sourcing strategy', '', '', '[{"en":"The sourcing strategy focused on reducing supplier concentration risk.","zh-TW":"採購策略專注於降低供應商集中風險。"},{"en":"Global sourcing strategies can reduce costs but increase complexity.","zh-TW":"全球採購策略可以降低成本但增加複雜性。"}]', 'phrasal verb'),
('spend analysis', '', '', '[{"en":"A spend analysis identified 500000 in potential annual savings.","zh-TW":"支出分析識別了每年50萬元的潛在節省。"},{"en":"Spend analysis is the foundation of a cost reduction initiative.","zh-TW":"支出分析是成本降低計劃的基礎。"}]', 'phrasal verb'),
('status quo', '', '', '[{"en":"Disrupting the status quo is necessary for meaningful change.","zh-TW":"打破現狀是實現有意義變革的必要條件。"},{"en":"Management decided to maintain the status quo until market conditions improve.","zh-TW":"管理層決定在市場條件改善之前維持現狀。"}]', 'phrasal verb'),
('statutory requirement', '', '', '[{"en":"All employers must comply with statutory requirements for minimum wage.","zh-TW":"所有雇主必須遵守最低工資的法定要求。"},{"en":"Failure to meet statutory requirements can result in criminal charges.","zh-TW":"未能達到法定要求可能導致刑事指控。"}]', 'phrasal verb'),
('stock market', '', '', '[{"en":"The stock market reacted negatively to the news.","zh-TW":"股市對這一消息作出了負面反應。"},{"en":"Stock market returns outpaced inflation over the long term.","zh-TW":"長期來看，股市回報超過了通貨膨脹。"}]', 'phrasal verb'),
('strategic plan', '', '', '[{"en":"The company released a new five-year strategic plan.","zh-TW":"公司發布了新的五年戰略計劃。"},{"en":"The strategic plan focuses on technology and sustainability.","zh-TW":"戰略計劃聚焦於技術和可持續性。"}]', 'phrasal verb'),
('subscription model', '', '', '[{"en":"The software company moved to a subscription model for recurring revenue.","zh-TW":"軟體公司轉向了訂閱模式以獲得經常性收入。"},{"en":"A subscription model improves revenue predictability.","zh-TW":"訂閱模式提高了收入的可預測性。"}]', 'phrasal verb'),
('supply-demand balance', '', '', '[{"en":"Rising raw material costs disturbed the supply-demand balance.","zh-TW":"原材料成本上漲擾亂了供需平衡。"},{"en":"Market prices adjust automatically to restore supply-demand balance.","zh-TW":"市場價格自動調整以恢復供需平衡。"}]', 'phrasal verb'),
('sustainability report', '', '', '[{"en":"The company''s sustainability report highlighted its carbon reduction goals.","zh-TW":"公司的可持續發展報告強調了其碳減排目標。"},{"en":"Investors increasingly consider sustainability reports when making decisions.","zh-TW":"投資者在決策時越來越考慮可持續發展報告。"}]', 'phrasal verb'),
('systematic risk', '', '', '[{"en":"Diversification cannot eliminate systematic risk.","zh-TW":"多元化無法消除系統性風險。"},{"en":"Interest rate changes are a major source of systematic risk.","zh-TW":"利率變化是系統性風險的主要來源。"}]', 'phrasal verb'),
('technical specification', '', '', '[{"en":"The technical specifications must be met before product approval.","zh-TW":"在產品批准前必須達到技術規格。"},{"en":"The supplier confirmed it could meet all technical specifications.","zh-TW":"供應商確認可以滿足所有技術規格。"}]', 'phrasal verb'),
('trade agreement', '', '', '[{"en":"The two countries signed a trade agreement to reduce tariffs.","zh-TW":"兩國簽署了減少關稅的貿易協定。"},{"en":"Regional trade agreements have expanded markets for exporters.","zh-TW":"區域貿易協定為出口商擴大了市場。"}]', 'phrasal verb'),
('trade credit', '', '', '[{"en":"The company uses 60-day trade credit to manage cash flow.","zh-TW":"公司使用60天商業信貸來管理現金流。"},{"en":"Trade credit is the most common form of short-term financing.","zh-TW":"商業信貸是最常見的短期融資形式。"}]', 'phrasal verb'),
('trade license', '', '', '[{"en":"All businesses must obtain a trade license before commencing operations.","zh-TW":"所有企業必須在開始經營前獲得營業執照。"},{"en":"The restaurant lost its trade license due to safety violations.","zh-TW":"餐廳因安全違規失去了營業執照。"}]', 'phrasal verb'),
('trade receivables', '', '', '[{"en":"The company reported a 10 million increase in trade receivables.","zh-TW":"公司報告貿易應收帳款增加了1000萬元。"},{"en":"Trade receivables are listed under current assets on the balance sheet.","zh-TW":"貿易應收帳款在資產負債表上列為流動資產。"}]', 'phrasal verb'),
('treasury bonds', '', '', '[{"en":"Investors shifted to treasury bonds during market volatility.","zh-TW":"市場波動期間，投資者轉向了國庫債券。"},{"en":"Treasury bond yields are used as a benchmark for other interest rates.","zh-TW":"國庫債券收益率被用作其他利率的基準。"}]', 'phrasal verb'),
('two-way communication', '', '', '[{"en":"Good leadership requires two-way communication, not just top-down messages.","zh-TW":"良好的領導力需要雙向溝通，不僅僅是自上而下的信息。"},{"en":"The survey opened a channel for two-way communication with employees.","zh-TW":"調查開啟了與員工雙向溝通的渠道。"}]', 'phrasal verb'),
('unit economics', '', '', '[{"en":"The startup''s unit economics showed strong margins at scale.","zh-TW":"新創公司的單位經濟學在規模化時顯示出強勁的利潤率。"},{"en":"Positive unit economics are essential for a sustainable business model.","zh-TW":"正向的單位經濟學對可持續的商業模式至關重要。"}]', 'phrasal verb'),
('valuation multiples', '', '', '[{"en":"The acquisition was priced at 15 times earnings based on industry valuation multiples.","zh-TW":"收購按行業估值倍數的15倍盈利定價。"},{"en":"Valuation multiples vary widely across different sectors.","zh-TW":"不同行業的估值倍數差異很大。"}]', 'phrasal verb'),
('wealth management', '', '', '[{"en":"She engaged a wealth management firm to manage her investment portfolio.","zh-TW":"她聘請了一家財富管理公司管理她的投資組合。"},{"en":"Wealth management services include tax planning and estate management.","zh-TW":"財富管理服務包括稅務規劃和遺產管理。"}]', 'phrasal verb'),
('weighted average', '', '', '[{"en":"Weighted average cost of capital reflects both debt and equity costs.","zh-TW":"加權平均資本成本反映了債務和股本成本。"},{"en":"The portfolio return was calculated as a weighted average across all holdings.","zh-TW":"投資組合回報按所有持倉的加權平均計算。"}]', 'phrasal verb'),
('wholesale price', '', '', '[{"en":"Retailers buy at wholesale prices and sell at retail prices.","zh-TW":"零售商以批發價購買並以零售價出售。"},{"en":"A reduction in wholesale prices helped retailers improve margins.","zh-TW":"批發價格的降低幫助零售商提高了利潤率。"}]', 'phrasal verb'),
('year-end closing', '', '', '[{"en":"Year-end closing requires reconciling all accounts and reversing accruals.","zh-TW":"年終結帳需要對帳所有帳目並沖回應計項目。"},{"en":"The finance team starts year-end closing preparations in November.","zh-TW":"財務團隊在11月開始年終結帳準備工作。"}]', 'phrasal verb'),
('yield curve', '', '', '[{"en":"An inverted yield curve is often seen as a recession signal.","zh-TW":"殖利率曲線倒掛通常被視為衰退信號。"},{"en":"The yield curve steepened as long-term rates rose faster than short-term.","zh-TW":"隨著長期利率比短期利率上升得更快，殖利率曲線趨陡了。"}]', 'phrasal verb'),
('zero coupon bond', '', '', '[{"en":"Zero coupon bonds are popular for long-term retirement planning.","zh-TW":"零息債券在長期退休規劃中很受歡迎。"},{"en":"The return on a zero coupon bond comes entirely from the discount.","zh-TW":"零息債券的回報完全來自折扣差價。"}]', 'phrasal verb'),
('budget variance', '', '', '[{"en":"A 10% favorable budget variance was reported in Q2.","zh-TW":"第二季度報告了10%的有利預算差異。"},{"en":"Budget variance reports are reviewed monthly by department heads.","zh-TW":"預算差異報告每月由部門主管審查。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('business entity', '', '', '[{"en":"A limited liability company is the most popular business entity type.","zh-TW":"有限責任公司是最受歡迎的商業實體類型。"},{"en":"Each business entity must file separate tax returns.","zh-TW":"每個商業實體必須單獨申報稅務。"}]', 'phrasal verb'),
('business model', '', '', '[{"en":"The company pivoted its business model to focus on subscriptions.","zh-TW":"公司將其商業模式轉向了訂閱服務。"},{"en":"A scalable business model supports rapid growth without proportional cost increases.","zh-TW":"可擴展的商業模式支持快速增長而不帶來同比例的成本增加。"}]', 'phrasal verb'),
('business plan', '', '', '[{"en":"Investors required a detailed business plan before committing funds.","zh-TW":"投資者在承諾資金前要求了詳細的商業計劃書。"},{"en":"The business plan projected profitability within 18 months.","zh-TW":"商業計劃預計在18個月內達到盈利。"}]', 'phrasal verb'),
('call center', '', '', '[{"en":"The company outsourced its call center operations to reduce costs.","zh-TW":"公司外包了其客服中心業務以降低成本。"},{"en":"Response times at the call center improved after additional staffing.","zh-TW":"增加人員後，客服中心的響應時間有所改善。"}]', 'phrasal verb'),
('cancellation fee', '', '', '[{"en":"The hotel charged a one-night cancellation fee for late cancellations.","zh-TW":"酒店對逾期取消收取一晚的取消費。"},{"en":"The supplier agreed to waive the cancellation fee as a goodwill gesture.","zh-TW":"供應商同意作為善意表示豁免取消費。"}]', 'phrasal verb'),
('capital gains tax', '', '', '[{"en":"Capital gains tax is applied when shares are sold at a profit.","zh-TW":"股票以盈利出售時適用資本利得稅。"},{"en":"Some countries offer relief from capital gains tax for long-term holdings.","zh-TW":"一些國家為長期持有提供資本利得稅減免。"}]', 'phrasal verb'),
('carousel ad', '', '', '[{"en":"Carousel ads on social media generated a 20% higher click rate.","zh-TW":"社群媒體上的輪播廣告產生了高20%的點擊率。"},{"en":"The team created a carousel ad showcasing the five product variants.","zh-TW":"團隊創建了展示五款產品變體的輪播廣告。"}]', 'phrasal verb'),
('cash reserve', '', '', '[{"en":"A three-month cash reserve provides a safety net for the business.","zh-TW":"三個月的現金儲備為企業提供了安全保障。"},{"en":"The company dipped into its cash reserves during the sales slump.","zh-TW":"銷售低迷期間，公司動用了現金儲備。"}]', 'phrasal verb'),
('certificate of origin', '', '', '[{"en":"A certificate of origin is required for customs clearance in many countries.","zh-TW":"許多國家通關時需要原產地證書。"},{"en":"The certificate of origin confirmed the goods were made in Taiwan.","zh-TW":"原產地證書確認了商品在台灣製造。"}]', 'phrasal verb'),
('charge off', '', '', '[{"en":"The bank charged off 10 million in non-performing loans.","zh-TW":"銀行核銷了1000萬元的不良貸款。"},{"en":"A high charge-off rate signals poor credit quality in the portfolio.","zh-TW":"高核銷率表明投資組合中的信用品質差。"}]', 'phrasal verb'),
('claims processing', '', '', '[{"en":"Digital tools reduced claims processing time from 10 days to 3 days.","zh-TW":"數位工具將索賠處理時間從10天縮短到了3天。"},{"en":"Efficient claims processing improves customer satisfaction significantly.","zh-TW":"高效的索賠處理顯著改善了客戶滿意度。"}]', 'phrasal verb'),
('client relationship', '', '', '[{"en":"Building strong client relationships is essential for account retention.","zh-TW":"建立強大的客戶關係對帳戶保留至關重要。"},{"en":"Regular check-ins are key to nurturing long-term client relationships.","zh-TW":"定期拜訪是培養長期客戶關係的關鍵。"}]', 'phrasal verb'),
('close of business', '', '', '[{"en":"Please send the report by close of business Friday.","zh-TW":"請在週五下班時間前發送報告。"},{"en":"The decision must be finalized by close of business today.","zh-TW":"決定必須在今天下班時間前敲定。"}]', 'phrasal verb'),
('closing costs', '', '', '[{"en":"Closing costs for the property purchase totaled 2% of the sale price.","zh-TW":"房產購買的交割費用共計銷售價格的2%。"},{"en":"The buyer negotiated for the seller to cover closing costs.","zh-TW":"買方談判讓賣方承擔交割費用。"}]', 'phrasal verb'),
('commercial law', '', '', '[{"en":"Commercial law governs contracts, employment, and company matters.","zh-TW":"商法規範合約、就業和公司事務。"},{"en":"The company retained a specialist in commercial law for the acquisition.","zh-TW":"公司聘請了商法專家負責收購事宜。"}]', 'phrasal verb'),
('compulsory redundancy', '', '', '[{"en":"The company tried to avoid compulsory redundancy through redeployment.","zh-TW":"公司試圖通過內部調配避免強制裁員。"},{"en":"Compulsory redundancy must follow legal notice and consultation requirements.","zh-TW":"強制裁員必須遵守法定通知和諮詢要求。"}]', 'phrasal verb'),
('consulting firm', '', '', '[{"en":"The company hired a consulting firm to review its operations.","zh-TW":"公司聘請了一家諮詢公司審查其業務。"},{"en":"Top consulting firms offer expertise across strategy, finance, and operations.","zh-TW":"頂級諮詢公司在戰略、財務和運營方面提供專業知識。"}]', 'phrasal verb'),
('contingent liability', '', '', '[{"en":"The company disclosed a contingent liability for the ongoing lawsuit.","zh-TW":"公司披露了正在進行的訴訟的或有負債。"},{"en":"Contingent liabilities are noted in the financial statement footnotes.","zh-TW":"或有負債在財務報表附注中說明。"}]', 'phrasal verb'),
('contribution margin', '', '', '[{"en":"The contribution margin analysis showed which products were most profitable.","zh-TW":"貢獻毛利分析顯示了哪些產品最有利可圖。"},{"en":"A high contribution margin means more revenue is available for fixed costs.","zh-TW":"高貢獻毛利意味著有更多收入可用於覆蓋固定成本。"}]', 'phrasal verb'),
('corporate headquarters', '', '', '[{"en":"The corporate headquarters was relocated to reduce operating costs.","zh-TW":"企業總部遷移以降低運營成本。"},{"en":"All major decisions are made at the corporate headquarters.","zh-TW":"所有重大決策都在企業總部做出。"}]', 'phrasal verb'),
('corporate loan', '', '', '[{"en":"The company secured a 20 million corporate loan to fund its expansion.","zh-TW":"公司獲得了2000萬元的企業貸款為其擴張提供資金。"},{"en":"Corporate loans typically carry lower interest rates than personal loans.","zh-TW":"企業貸款通常比個人貸款利率更低。"}]', 'phrasal verb'),
('corporate strategy', '', '', '[{"en":"The board approved a corporate strategy focused on Asia-Pacific growth.","zh-TW":"董事會批准了專注於亞太增長的企業策略。"},{"en":"Corporate strategy guides resource allocation across business units.","zh-TW":"企業策略指導業務部門的資源分配。"}]', 'phrasal verb'),
('cost allocation', '', '', '[{"en":"A fair cost allocation method is essential for accurate product pricing.","zh-TW":"公平的成本分配方法對準確的產品定價至關重要。"},{"en":"The finance team revised the cost allocation formula for shared services.","zh-TW":"財務團隊修訂了共享服務的成本分配公式。"}]', 'phrasal verb'),
('cost leadership', '', '', '[{"en":"The company pursued a cost leadership strategy through lean production.","zh-TW":"公司通過精益生產追求成本領導戰略。"},{"en":"Cost leadership enables the firm to undercut competitor prices.","zh-TW":"成本領導使公司能夠以低於競爭對手的價格銷售。"}]', 'phrasal verb'),
('customer churn', '', '', '[{"en":"High customer churn is a warning sign of poor service or value.","zh-TW":"高客戶流失率是服務或價值差的警告信號。"},{"en":"The company invested in loyalty programs to reduce customer churn.","zh-TW":"公司投資忠誠計劃以降低客戶流失。"}]', 'phrasal verb'),
('days sales outstanding', '', '', '[{"en":"The company reduced its days sales outstanding from 60 to 45 days.","zh-TW":"公司將應收帳款天數從60天縮短到了45天。"},{"en":"A lower days sales outstanding indicates more efficient cash collection.","zh-TW":"較低的應收帳款天數表明更高效的現金收款。"}]', 'phrasal verb'),
('debt ratio', '', '', '[{"en":"A debt ratio above 60% may concern lenders about repayment ability.","zh-TW":"60%以上的負債比率可能使貸款方對還款能力感到擔憂。"},{"en":"The company lowered its debt ratio by selling non-core assets.","zh-TW":"公司通過出售非核心資產降低了負債比率。"}]', 'phrasal verb'),
('debt restructuring', '', '', '[{"en":"The company entered debt restructuring negotiations with its creditors.","zh-TW":"公司與債權人進行了債務重組談判。"},{"en":"Debt restructuring extended repayment terms by five years.","zh-TW":"債務重組將還款期延長了五年。"}]', 'phrasal verb'),
('disclosure statement', '', '', '[{"en":"The company issued a disclosure statement before the public offering.","zh-TW":"公司在公開發行前發出了披露聲明。"},{"en":"Investors rely on the disclosure statement to make informed decisions.","zh-TW":"投資者依靠披露聲明做出明智的決策。"}]', 'phrasal verb'),
('double taxation', '', '', '[{"en":"A tax treaty helps businesses avoid double taxation on overseas income.","zh-TW":"稅務協定幫助企業避免對海外收入雙重課稅。"},{"en":"Double taxation discourages cross-border investment.","zh-TW":"雙重課稅阻礙了跨境投資。"}]', 'phrasal verb'),
('draft contract', '', '', '[{"en":"The legal team reviewed the draft contract for any unfavorable clauses.","zh-TW":"法律團隊審查了合約草案中任何不利的條款。"},{"en":"Please sign and return the draft contract after review.","zh-TW":"請審閱後簽署並歸還合約草案。"}]', 'phrasal verb'),
('employee benefits', '', '', '[{"en":"Comprehensive employee benefits helped the company attract top talent.","zh-TW":"全面的員工福利幫助公司吸引了頂尖人才。"},{"en":"Employee benefits include health insurance, pension, and paid leave.","zh-TW":"員工福利包括健康保險、退休金和帶薪假期。"}]', 'phrasal verb'),
('employee handbook', '', '', '[{"en":"New employees receive an employee handbook on their first day.","zh-TW":"新員工在第一天收到員工手冊。"},{"en":"The employee handbook was revised to include the new remote work policy.","zh-TW":"員工手冊修訂納入了新的遠程工作政策。"}]', 'phrasal verb'),
('end user', '', '', '[{"en":"The software is designed with the end user experience in mind.","zh-TW":"軟體的設計以最終用戶體驗為重心。"},{"en":"Feedback from end users guided the second version of the product.","zh-TW":"最終用戶的反饋指導了產品第二版的開發。"}]', 'phrasal verb'),
('estate planning', '', '', '[{"en":"Estate planning ensures assets are distributed according to your wishes.","zh-TW":"遺產規劃確保資產按照您的意願分配。"},{"en":"The wealth manager provided comprehensive estate planning services.","zh-TW":"財富管理者提供了全面的遺產規劃服務。"}]', 'phrasal verb'),
('expenditure review', '', '', '[{"en":"The expenditure review revealed 10% in wasteful spending.","zh-TW":"支出審查揭示了10%的浪費性支出。"},{"en":"All departments participated in the annual expenditure review.","zh-TW":"所有部門參與了年度支出審查。"}]', 'phrasal verb'),
('export license', '', '', '[{"en":"A special export license was required for the controlled technology.","zh-TW":"受管制技術需要特殊出口許可證。"},{"en":"The export license was delayed due to additional security checks.","zh-TW":"由於額外的安全檢查，出口許可證被延遲了。"}]', 'phrasal verb'),
('external financing', '', '', '[{"en":"The startup sought external financing to accelerate growth.","zh-TW":"新創公司尋求外部融資以加速增長。"},{"en":"External financing includes bank loans, bonds, and equity issuance.","zh-TW":"外部融資包括銀行貸款、債券和股本發行。"}]', 'phrasal verb'),
('fair competition', '', '', '[{"en":"The regulator oversees markets to ensure fair competition.","zh-TW":"監管機構監督市場以確保公平競爭。"},{"en":"Fair competition benefits consumers through lower prices and better quality.","zh-TW":"公平競爭通過更低的價格和更好的品質使消費者受益。"}]', 'phrasal verb'),
('fast-moving consumer goods', '', '', '[{"en":"The FMCG sector relies on high volumes and efficient distribution.","zh-TW":"快速消費品行業依賴於高產量和高效配送。"},{"en":"Fast-moving consumer goods require strong shelf presence in retail stores.","zh-TW":"快速消費品需要在零售店中有強大的貨架存在感。"}]', 'phrasal verb'),
('final accounts', '', '', '[{"en":"The final accounts were submitted to the auditors by March 31.","zh-TW":"最終帳目在3月31日前提交給了審計師。"},{"en":"Final accounts include the balance sheet and profit and loss account.","zh-TW":"最終帳目包括資產負債表和損益帳。"}]', 'phrasal verb'),
('financial health', '', '', '[{"en":"The acquisition target had strong financial health with low debt levels.","zh-TW":"收購目標擁有強劲的財務健康狀況和低債務水平。"},{"en":"Monthly reviews ensure the company maintains its financial health.","zh-TW":"月度審查確保公司維持其財務健康狀況。"}]', 'phrasal verb'),
('financial leverage', '', '', '[{"en":"Excessive financial leverage magnifies both gains and losses.","zh-TW":"過度的財務槓桿既放大了收益也放大了損失。"},{"en":"The company reduced financial leverage by paying down debt.","zh-TW":"公司通過還清債務減少了財務槓桿。"}]', 'phrasal verb'),
('financial stability', '', '', '[{"en":"A three-month cash reserve contributes to financial stability.","zh-TW":"三個月的現金儲備有助於財務穩定性。"},{"en":"The central bank monitors financial stability across the banking sector.","zh-TW":"中央銀行監測整個銀行業的財務穩定性。"}]', 'phrasal verb'),
('financial transaction', '', '', '[{"en":"Each financial transaction is logged in the general ledger.","zh-TW":"每筆財務交易都記錄在總帳中。"},{"en":"Anti-money laundering checks apply to large financial transactions.","zh-TW":"反洗錢檢查適用於大額金融交易。"}]', 'phrasal verb'),
('fixed overhead', '', '', '[{"en":"Fixed overhead includes rent, insurance, and management salaries.","zh-TW":"固定間接費用包括租金、保險和管理層薪資。"},{"en":"Higher output spreads fixed overhead over more units, reducing unit cost.","zh-TW":"更高的產量將固定間接費用分攤到更多單位，降低了單位成本。"}]', 'phrasal verb'),
('floating exchange rate', '', '', '[{"en":"Under a floating exchange rate, the currency adjusts to market conditions.","zh-TW":"在浮動匯率制度下，貨幣根據市場條件調整。"},{"en":"A floating exchange rate can create uncertainty for international traders.","zh-TW":"浮動匯率可能為國際貿易商創造不確定性。"}]', 'phrasal verb'),
('forecast accuracy', '', '', '[{"en":"High forecast accuracy reduces inventory and cash flow problems.","zh-TW":"高預測準確度降低了庫存和現金流問題。"},{"en":"Machine learning improved the company''s sales forecast accuracy significantly.","zh-TW":"機器學習顯著提高了公司的銷售預測準確度。"}]', 'phrasal verb'),
('fund management', '', '', '[{"en":"The pension fund outsourced its fund management to a specialist firm.","zh-TW":"退休金外包了其基金管理給專業公司。"},{"en":"Fund management requires balancing risk and return for investors.","zh-TW":"基金管理需要為投資者平衡風險和回報。"}]', 'phrasal verb'),
('gain on disposal', '', '', '[{"en":"The sale of the building resulted in a gain on disposal of 5 million.","zh-TW":"出售大樓帶來了500萬元的處置收益。"},{"en":"Gains on disposal are recorded in the income statement.","zh-TW":"出售收益在損益表中記錄。"}]', 'phrasal verb');